(window.NTDATA=window.NTDATA||{});(NTDATA.cass=NTDATA.cass||{}).rev={"1":{"1":"Откровение Иисуса Христа, которое дал Ему Бог,\nчтобы показать рабам Своим, чему должно произойти\nвскоре, и которое Он дал как знамение, послав через\nангела Своего рабу Своему Иоанну,","2":"который засвидетельствовал слово Божие и\nсвидетельство Иисуса Христа: всё, что он видел,","3":"Блажен читающий и слышащие слова этого\nпророчества и соблюдающие написанное в нем, ибо\nвремя близко.","4":"Иоанн семи церквам в Асии: благодать вам и мир\nот Того, Кто есть и Кто был и Кто грядет, и от семи\nдухов, которые пред престолом Его,","5":"и от Иисуса Христа, Который – Свидетель верный,\nПервородный из мёртвых и Начальник царей земных.\nЛюбящему нас, и избавившему нас от грехов наших\nкровью Своею","6":"и соделавшему нас царством, священниками Богу\nи Отцу Своему, Ему слава и держава во веки веков,\nаминь.","7":"Вот Он грядет с облаками и увидит Его всякое око\nи те, которые Его пронзили, и о Нем будут бить себя в\nгрудь все племена земные. Да, аминь.","8":"Я – Альфа и Омега, говорит Господь Бог, Тот, Кто\nесть и Кто был и Кто грядет, Вседержитель.","9":"Я, Иоанн, брат ваш и соучастник в скорби и\nцарстве\nи\nтерпении\nв\nИисусе,\nбыл\nна\nострове,\nназываемом Патмос, за слово Божие и свидетельство\nИисуса.","10":"Я был в Духе в день Господень и услышал позади\nсебя голос великий, словно трубы,","11":"которая говорила: то, что видишь, напиши в\nкнигу и пошли семи церквам: в Ефес, и в Смирну, и в\nПергам, и в Фиатиры, и в Сарды, и в Филадельфию и в\nЛаодикию.","12":"я обернулся посмотреть голос, который говорил\nсо мной, и, обернувшись, увидел семь светильников\nзолотых,","13":"и\nмежду\nсветильниками\nПодобного\nсыну\nчеловека, одетого в длинную до ног одежду и по грудь\nопоясанного золотым поясом.","14":"Голова же Его и волосы белы, как белая шерсть,\nкак снег, и глаза Его, как пламя огня,","15":"и ноги Его подобны меди, словно раскалённой в\nпечи, и голос Его, как голос вод многих:","16":"и Он держал в правой руке Своей семь звезд, и\nиз уст Его исходил меч обоюдоострый, и облик Его, как\nсолнце, когда оно сияет в силе своей.","17":"И когда я увидел Его, я упал к ногам Его, как\nмёртвый, и Он положил правую Свою руку на меня,\nговоря: не бойся; Я – Первый и Последний,","18":"и Живущий; и Я был мёртв, и вот Я жив во веки\nвеков, и имею ключи смерти и ада.","19":"Итак напиши, что ты видел, и что есть, и чему\nдолжно произойти после этого.","20":"Тайна семи звезд, которые ты видел в правой\nМоей руке, и семи светильников золотых: семь звезд –\nангелы семи церквей, и семь светильников – семь\nцерквей."},"2":{"1":"Ангелу церкви в Ефесе напиши: Так говорит\nДержащий семь звезд в правой Своей руке, Ходящий\nмежду семью светильниками золотыми:","2":"«знаю дела твои и труд и терпение твое и что ты\nне можешь переносить злых, и испытал называющих\nсебя апостолами, а они не апостолы, и нашел их\nлжецами,","3":"И имеешь терпение и много перенёс за имя Мое, и\nне изнемог.","4":"Но имею против тебя, что ты оставил первую\nлюбовь твою.","5":"Итак помни, откуда ты ниспал, и покайся, и твори\nпрежние дела. А если не так, приду к тебе и сдвину\nсветильник твой с места его, если не покаешься.","6":"Но то у тебя есть, что ненавидишь дела\nНиколаитов, которые и Я ненавижу.","7":"Имеющий ухо да услышит, что Дух говорит\nцерквам. Тому, кто побеждает, Я дам ему вкусить от\nдрева жизни, которое в раю Божием».","8":"И ангелу церкви в Смирне напиши: Так говорит\nПервый и Последний, Который был мёртв и ожил:","9":"«знаю твою скорбь и нищету, – но ты богат, – и\nхулу от говорящих, что они Иудеи, а они не Иудеи, но\nсинагога сатаны.","10":"Не бойся ничего, что тебе предстоит претерпеть.\nВот будет диавол ввергать из среды вас в тюрьму,\nчтобы быть вам искушенными, и будете иметь скорбь\nдесять дней. Будь верен до смерти, и дам тебе венец\nжизни.","11":"Имеющий ухо да услышит, что Дух говорит\nцерквам. Тот, кто побеждает, не будет поражен вовсе\nсмертью второй».","12":"И ангелу церкви в Пергаме напиши: Так говорит\nИмеющий меч обоюдоострый:","13":"«знаю, где ты живёшь: там, где престол сатаны.\nИ ты твердо держишься имени Моего и не отрекся от\nверы в Меня даже во дни Антипы, свидетеля Моего,\nверного Моего, который был убит у вас, там, где сатана\nживёт.","14":"Но имею немного против тебя за то, что ты\nимеешь там держащихся учения Валаама, который\nнаучил\nВалака\nпоставить\nзападню\nперед\nсынами\nИзраилевыми: есть идоложертвенное и блудить.","15":"Так и у тебя есть подобным же образом\nдержащиеся учения Николаитов.","16":"Итак покайся. Если же нет, приду к тебе скоро и\nсражусь с ними мечом уст Моих.","17":"Имеющий ухо да услышит, что Дух говорит\nцерквам. Тому, кто побеждает, Я дам ему манны\nсокровенной, и дам ему белый камешек, и на камешке\nимя новое написанное, которого никто не знает, кроме\nполучающего».","18":"И ангелу церкви в Фиатирах напиши: Так говорит\nСын Божий, у Которого глаза, как пламя огня, и ноги Его\nподобны меди:","19":"«знаю твои дела, и любовь, и веру, и служение и\nтерпение твое, и что дела твои последние больше\nпервых.","20":"Но имею против тебя, что ты попускаешь\nженщине Иезавели, называющей себя пророчицей; она\nи учит и вводит в заблуждение Моих рабов, чтобы они\nблудили и ели идоложертвенное.","21":"И Я дал ей время, чтобы она покаялась, но она не\nхочет покаяться в блуде своем.","22":"Вот Я повергаю её на одр страдания, и\nпрелюбодействующих с ней в скорбь великую, если не\nпокаются в делах её,","23":"и детей её убью смертью; и познают все церкви,\nчто Я – Испытующий внутренности и сердца, и воздам\nвам каждому по делам вашим.","24":"Вам\nже\nговорю,\nпрочим\nнаходящимся\nв\nФиатирах, всем, кто не имеют этого учения, которые не\nпознали глубин сатаны, как они говорят: не налагаю на\nвас другого бремени.","25":"Только то, что имеете, твердо держите, пока не\nприду.","26":"И тому, кто побеждает и кто соблюдает до конца\nдела Мои, Я дам ему власть над язычниками,","27":"и он будет пасти их посохом железным; как\nсосуды глиняные, они будут сокрушены, – как и Я\nполучил власть от Отца Моего;","28":"и дам ему звезду утреннюю.","29":"Имеющий ухо да услышит, что Дух говорит\nцерквам»."},"3":{"1":"И ангелу церкви в Сардах напиши: Так говорит\nИмеющий семь духов Божиих и семь звезд: «знаю твои\nдела; ты имеешь имя, будто жив, но ты мёртв.","2":"Будь бодрствующим и утверди прочее, чему\nпредстоит\nумереть,\nибо\nЯ\nне\nнашел\nдела\nтвои\nсовершенными пред Богом Моим.","3":"Итак помни, как ты получил то, что имеешь, и как\nуслышал, и храни и покайся. Если же не будешь\nбодрствовать, то Я приду, как вор, и ты не узнаешь, в\nкоторый час приду на тебя.","4":"Но у тебя в Сардах есть немногие, которые не\nосквернили одежд своих и будут ходить со Мной в\nбелом, потому что они достойны:","5":"тот, кто так побеждает, облечётся в одежды\nбелые, и Я не изглажу имени его из книги жизни и\nисповедую имя его пред Отцом Моим и пред ангелами\nЕго.","6":"Имеющий ухо да услышит, что Дух говорит\nцерквам».","7":"И ангелу церкви в Филадельфии напиши: Так\nговорит Святой, Истинный, имеющий ключ Давидов,\nотворяющий – и никто не затворит, и затворяющий – и\nникто не отворяет:","8":"«знаю твои дела; вот Я держу перед тобой дверь\nотверстую, (никто не может затворить её), потому что\nмалую имеешь силу, и соблюл Мое слово, и не отрекся\nот имени Моего.","9":"Вот я даю из синагоги сатаны, из тех, которые\nговорят, что они Иудеи – и они не Иудеи, но лгут, – вот Я\nсделаю с ними, чтобы они пришли и преклонились пред\nногами твоими и познали, что Я возлюбил тебя.","10":"А, как ты соблюл слово терпения Моего, соблюду\nи Я тебя от часа искушения, грядущего на всю\nвселенную, искусить живущих на земле,","11":"Иду скоро: держи твердо, что имеешь, чтобы\nникто не забрал венца твоего.","12":"Того, кто побеждает, Я сделаю его столпом в\nхраме Бога Моего, и он уже не выйдет вон, и напишу на\nнем имя Бога Моего и имя города Бога Моего, нового\nИерусалима, нисходящего с неба от Бога Моего, и имя\nМое новое.","13":"Имеющий ухо да услышит, что Дух говорит\nцерквам».","14":"И ангелу церкви в Лаодикии напиши: Так говорит\nАминь, Свидетель верный и истинный, Начало творения\nБожия:","15":"«знаю твои дела; ты и не холоден и не горяч. О,\nесли бы ты был холоден или горяч!","16":"Но, как ты тёпл и не горяч, ни холоден, то\nизвергну тебя из уст Моих.","17":"Потому что ты говоришь: я богат и разбогател, и\nни в чем нужды не имею, и не знаешь, что ты\nнесчастнее всех и жалок, и нищ, и слеп и наг,–","18":"советую тебе купить у Меня золото, раскалённое\nв огне, чтобы тебе обогатиться; и одежды белые, чтобы\nтебе одеться, и чтобы не открылась срамота наготы\nтвоей; и глазную мазь, чтобы помазать глаза твои,\nчтобы видеть.","19":"Всех, кого Я люблю, Я обличаю и наказываю.\nИтак будь ревностен и покайся.","20":"Вот, Я стою у двери и стучусь: если кто услышит\nголос Мой и отворит дверь, Я войду к нему и буду\nвечерять с ним, и он со Мною.","21":"Тому, кто побеждает, Я дам ему сесть со Мною на\nпрестоле Моем, как и Я победил и сел с Отцом Моим на\nпрестоле Его.","22":"Имеющий ухо да услышит, что Дух говорит\nцерквам»."},"4":{"1":"После этого я увидел, и вот дверь отверстая на\nнебе, и тот голос первый, который я слышал, словно\nтрубы, говорившей со мной, сказал: взойди сюда, и\nпокажу тебе, чему должно произойти после этого.","2":"И тотчас я был в Духе: и вот, престол стоял на\nнебе, и на престоле Сидящий,","3":"и Сидящий, видом подобный камню яспису и\nсардису, и радуга вокруг престола, видом подобная\nизумруду.","4":"И вокруг престола двадцать четыре престола, и на\nпрестолах\nдвадцать\nчетыре\nстарца\nсидящих,\nоблечённых в одежды белые, и на головах их венцы\nзолотые.","5":"И от престола исходят молнии и голоса и громы. И\nсемь светочей огненных, горящих пред престолом,\nкоторые суть семь духов Божиих.","6":"И пред престолом словно море стеклянное,\nподобное кристаллу. И посреди престола и вокруг\nпрестола четыре животных полных глаз спереди и\nсзади.","7":"И первое животное подобно льву, и второе\nживотное подобно тельцу, и третье животное имело\nлицо словно человеческое, и четвёртое животное\nподобно орлу летящему.","8":"И четыре животных, каждое из них имело по\nшести крыльев, кругом и изнутри они полны глаз, и\nнепрестанно день и ночь говорят: Свят, Свят, Свят\nГосподь Бог Вседержитель, Тот, Кто был и Кто есть и\nКто грядет.","9":"И когда воздают животные славу и честь и\nблагодарение Сидящему на престоле, Живущему во\nвеки веков, –","10":"двадцать четыре старца падают пред Сидящим\nна престоле и поклоняются Живущему во веки веков и\nповергают венцы свои пред престолом, говоря:","11":"Достоин Ты, Господь и Бог наш, принять славу и\nчесть и силу, потому что Ты сотворил всё, и по Твоей\nволе всё существовало и всё создано."},"5":{"1":"И я увидел в правой руке Сидящего на престоле\nкнигу, писанную изнутри и снаружи, запечатанную\nсемью печатями.","2":"И я увидел ангела сильного, провозглашающего\nголосом великим: кто достоин раскрыть книгу и снять\nпечати её?","3":"И никто не мог ни на небе, ни на земле, ни под\nземлей раскрыть книгу и посмотреть в неё.","4":"И я плакал много, что никого достойного не\nнашлось раскрыть книгу и посмотреть в неё.","5":"И один из старцев говорит мне: не плачь; вот\nпобедил Лев из колена Иудина, Корень Давидов, чтобы\nраскрыть книгу и семь печатей её.","6":"И я увидел посреди престола и четырех животных\nи посреди старцев Агнца стоящего, словно закланного,\nимеющего семь рогов и семь глаз, которые суть семь\nдухов Божиих, посланных во всю землю.","7":"И Он пришел и взял книгу из правой руки\nСидящего на престоле.","8":"И когда Он взял книгу, четыре животных и\nдвадцать четыре старца пали пред Агнцем, имея\nкаждый гусли и золотые чаши, полные фимиама,\nкоторые суть молитвы святых.","9":"И они поют песнь новую, говоря: Достоин Ты взять\nкнигу и открыть печати её, потому что Ты был заклан и\nискупил Богу кровью Твоею людей из всякого колена и\nязыка и народа и племени,","10":"и\nсоделал\nих\nБогу\nнашему\nцарством\nи\nсвященниками, и они будут царствовать на земле.","11":"И я увидел, и услышал голос ангелов многих\nвокруг престола и животных и старцев, и было число их\nтьмы тем и тысячи тысяч,","12":"говорящих голосом великим: Достоин Агнец\nзакланный принять силу, и богатство, и премудрость, и\nкрепость, и честь, и славу и благословение.","13":"И всякое творение, что на небе и на земле и под\nземлей и на море, и всё, что в них, услышал я, как они\nговорили:\nСидящему\nна\nпрестоле\nи\nАгнцу\nблагословение, и честь, и слава и держава, во веки\nвеков.","14":"И четыре животных говорили: аминь, и старцы\nпали и поклонились."},"6":{"1":"И я увидел, когда открыл Агнец одну из семи\nпечатей, и я услышал одно из четырех животных,\nговорящее словно голосом грома: иди.","2":"И я увидел, и вот конь белый и у сидящего на нем\nлук, и дан был ему венец, и вышел он, побеждая и\nчтобы победить,","3":"И, когда Он открыл вторую печать, я услышал\nвторое животное, говорящее: иди.","4":"И\nвышел\nдругой\nконь\nогненно-красный,\nи\nсидящему на нем, дано ему было забрать мир с земли, и\nчтобы стали друг друга убивать, и дан был ему меч\nвеликий.","5":"И когда Он открыл третью печать, я услышал\nтретье животное, говорящее: иди. И я увидел, и вот\nконь вороной, и у сидящего на нем весы в руке его.","6":"И я услышал словно голос посреди четырех\nживотных, говорящий: мера пшеницы за динарий, и три\nмеры ячменя за динарий. И елея и вина не повреждай.","7":"И, когда Он открыл четвёртую печать, я услышал\nголос четвёртого животного, говорящего: иди.","8":"И я увидел, и вот конь жёлто-зелёный, и сидящий\nна нем, имя ему смерть, и ад следовал за ним, и была\nдана им власть над четвёртой частью земли, чтобы\nубить людей мечом и голодом и мором и зверями\nземными.","9":"И, когда Он открыл пятую печать, я увидел под\nжертвенником души умерщвлённых за слово Божие и за\nсвидетельство, которое они имели.","10":"И возопили они голосом великим, говоря: доколе,\nВладыка Святой и Истинный, Ты не судишь и не мстишь\nза кровь нашу живущим на земле?","11":"И дано было им каждому одеяние белое, и было\nсказано им, чтобы подождали еще малое время, доколе\nне будет пополнено число их и соработников их и\nбратьев их, которые будут убиваемы, как и они.","12":"увидел, когда Он открыл шестую печать, и\nпроизошло великое землетрясение, и солнце стало\nчёрным, как вретище волосяное, и луна вся сделалась\nкак кровь,","13":"и звёзды небесные упали на землю, как\nсмоковница, потрясаемая великим ветром, сбрасывает\nнезрелые смоквы свои;","14":"и\nнебо\nотступило,\nкак\nсвиток,\nкоторый\nсвертывают, и всякая гора и остров были сдвинуты с\nмест своих.","15":"И цари земные, и вельможи, и тысяченачальники,\nи богатые, и сильные, и всякий раб и свободный\nскрылись в пещеры и в утесы гор,","16":"и говорят горам и скалам: падите на нас и\nскройте нас от лица Сидящего на престоле и от гнева\nАгнца,","17":"потому что пришел день великий гнева Их, и кто\nможет устоять?"},"7":{"1":"После этого я увидел четырех ангелов, стоящих на\nчетырех углах земли, держащих четыре ветра земли,\nчтобы не дул ветер ни на землю, ни на море, ни на\nкакое дерево.","2":"И я увидел другого ангела, восходящего от\nвостока солнца и имеющего печать Бога Живого. И\nвоззвал он голосом великим к четырем ангелам, к тем,\nкоторым было дано причинять вред земле и морю,","3":"говоря: не причиняйте вреда ни земле, ни морю,\nни деревьям, пока мы не запечатлеем рабов Бога\nнашего на челах их.","4":"И я услышал число запечатленных: сто сорок\nчетыре\nтысячи\nзапечатленных\nиз\nвсех\nколен\nИзраилевых:","5":"из\nколена\nИудина\nдвенадцать\nтысяч\nзапечатлённых, из колена Рувимова двенадцать тысяч,\nиз колена Гадова двенадцать тысяч,","6":"из колена Асирова двенадцать тысяч, из колена\nНеффалимова двенадцать тысяч, из колена Манассиина\nдвенадцать тысяч,","7":"из колена Симеонова двенадцать тысяч, из колена\nЛевиина двенадцать тысяч, из колена Иссахарова\nдвенадцать тысяч,","8":"из колена Завулонова двенадцать тысяч, из\nколена\nИосифова\nдвенадцать\nтысяч,\nиз\nколена\nВениаминова двенадцать тысяч запечатленных.","9":"После этого я увидел: и вот, великое множество\nлюдей, которого исчислить никто не мог, из всякого\nплемени и всех колен и народов и языков: они стоят\nпред престолом и пред Агнцем, облечённые в одеяния\nбелые, и пальмовые ветви в руках их.","10":"И восклицают они голосом великим, говоря:\nСпасение Богу нашему, сидящему на престоле, и Агнцу!","11":"И все ангелы стояли вокруг престола и старцев и\nчетырех животных, и упали пред престолом на лица\nсвои и поклонились Богу,","12":"говоря:\nАминь,\nблагословение,\nи\nслава,\nи\nпремудрость, и благодарение, и честь, и сила и\nкрепость Богу нашему во веки веков, аминь.","13":"И начал один из старцев и сказал мне: эти,\nоблечённые в одеяния белые, кто они и откуда пришли?","14":"И я сказал ему: господин мой, ты знаешь. И он\nсказал мне: это те, которые приходят от великой\nскорби, и которые омыли одеяния свои и убелили их\nкровью Агнца.","15":"Поэтому они – пред престолом Божиим, и служат\nЕму день и ночь в храме Его, и Сидящий на престоле\nраскинет шатер Свой над ними.","16":"И они не будут больше голодать и не будут\nбольше жаждать, и не будет палить их солнце и\nникакой зной,","17":"потому что Агнец посреди престола будет пасти\nих, и поведёт их на источники вод жизни, и отрёт Бог\nвсякую слезу с очей их.\nОткровение 8"},"8":{"1":"И когда Он открыл седьмую печать, сделалось\nмолчание на небе, словно на полчаса.","2":"И я увидел семь ангелов, которые стоят пред\nБогом, и даны были им семь труб.","3":"И другой ангел пришел и стал у жертвенника,\nдержа золотую кадильницу, и дано ему было много\nфимиама, чтобы он принёс его с молитвами всех святых\nна золотой жертвенник пред престолом.","4":"И вознёсся дым фимиама с молитвами святых пред\nБогом.","5":"И взял ангел кадильницу, и наполнил её огнем с\nжертвенника и бросил на землю, и произошли громы, и\nголоса, и молнии и землетрясение.","6":"И\nсемь\nангелов,\nимеющие\nсемь\nтруб,\nприготовились вострубить.","7":"И первый вострубил: и сделались град и огонь,\nсмешанные с кровью, и были брошены на землю; и\nтреть земли сгорела, и треть деревьев сгорела, и\nвсякая трава зелёная сгорела.","8":"И второй ангел вострубил: и словно великая гора,\nогнем горящая, была брошена в море, и сделалась\nтреть моря кровью,","9":"и умерла треть тварей в море, имеющих душу, и\nтреть судов погибла.","10":"И третий ангел вострубил: и упала с неба\nвеликая звезда, горящая как светоч, и упала на треть\nрек и на источники вод.","11":"И имя звезды – Полынь; и сделалась треть вод\nполынью; и многие из людей умерли от вод, потому что\nводы стали горьки.","12":"И четвёртый ангел вострубил: и поражена была\nтреть солнца и треть луны и треть звёзд с тем, чтобы\nтреть их померкла, и день потерял бы на треть свой\nсвет, и ночь также.","13":"И я увидел и услышал одного орла, летящего\nвысоко в небе, говорящего голосом великим: горе, горе,\nгоре живущим на земле от остальных трубных голосов\nтрех ангелов, которые будут трубить."},"9":{"1":"И пятый ангел вострубил, и я увидел звезду,\nупавшую с неба на землю, и дан был ей ключ от\nколодца бездны.","2":"И она отворила колодец бездны; и поднялся дым\nиз колодца, словно дым из великой печи, и помрачено\nбыло солнце и воздух дымом из колодца,","3":"И из дыма вышла саранча на землю, и дана была\nей власть, как имеют власть земные скорпионы.","4":"И сказано было ей, чтобы не причинила вреда\nтраве земной, и никакой зелени, и никакому дереву, но\nодним только людям, которые не имеют печати Божией\nна челах.","5":"И дано было ей не убить их, но чтобы они мучимы\nбыли пять месяцев: и мучение от неё словно мучение от\nскорпиона, когда он ужалит человека.","6":"И в дни те люди будут искать смерти и не найдут\nеё; и захотят они умереть, а смерть убегает от них.","7":"И саранча по виду своему подобна коням,\nприготовленным на сражение, и на головах у неё\nсловно венцы, подобные золоту, и лица у неё словно\nлица людей,","8":"и имела она волосы словно волосы у женщин, и\nзубы её были словно львиные;","9":"и она имела брони словно брони железные, и шум\nкрыльев её словно шум от колесниц, когда много коней\nбежит на сражение,","10":"И имеет она хвосты подобные скорпионам и\nжала, и в хвостах у неё – власть её причинять людям\nвред пять месяцев,","11":"Она имеет над собой царем ангела бездны; имя\nему по-еврейски Аваддон, а на греческом языке он\nимеет имя Аполлион.","12":"Первое горе прошло, вот идут еще два горя\nпосле этого.","13":"И шестой ангел вострубил: и я услышал голос от\nчетырех рогов жертвенника золотого, который пред\nБогом,","14":"говоривший шестому ангелу, тому который имел\nтрубу: развяжи четырех ангелов, связанных на реке\nвеликой Евфрате.","15":"И\nбыли\nразвязаны\nчетыре\nангела,\nприготовленные на день, и час, и месяц, и год, чтобы\nубить треть людей.","16":"И число конного войска – две тьмы тем: я\nуслышал число его.","17":"И так я увидел коней в видении и сидящих на\nних, имеющих брони огненные и гиацинтовые и серные;\nи головы коней словно головы львов, и из пасти их\nвыходит огонь и дым и сера.","18":"Этими тремя язвами была убита треть людей:\nогнем и дымом и серой, выходящей из их пастей.","19":"Ибо власть коней – в пасти их и в хвостах их: ибо\nхвосты их подобны змеям, имея головы, и ими они\nпричиняют вред.","20":"И прочие из людей, которые не были убиты этими\nязвами, даже не покаялись в делах своих, чтобы не\nпоклоняться бесам и идолам золотым, и серебряным, и\nмедным, и каменным и деревянным, которые ни видеть\nне могут, ни слышать, ни ходить;","21":"и не покаялись они ни в убийствах своих, ни в\nколдовствах своих, ни в блуде своем, ни в кражах своих."},"10":{"1":"И я увидел другого ангела сильного, сходящего с\nнеба, облечённого облаком; и радуга над головой его, и\nлицо его словно солнце, и ноги его словно столбы огня;","2":"и держал он в руке своей книжку раскрытую. И\nпоставил он ногу свою правую на море, левую же на\nземлю,","3":"и воскликнул голосом великим, как лев ревёт. И\nкогда\nон\nвоскликнул,\nпроговорили\nсемь\nгромов\nголосами своими.","4":"И, когда проговорили семь громов, я намеревался\nписать; и услышал я голос с неба, говорящий: запечатай\nто, что проговорили семь громов и не пиши этого.","5":"И ангел, которого я видел стоящим на море и на\nземле, поднял руку свою правую к небу,","6":"и поклялся Живущим во веки веков, Который\nсотворил небо и то, что на нём, и землю и то, что на\nней, и море и то, что в нём, что времени больше не\nбудет;","7":"но во дни, когда возгласит седьмой ангел, когда\nон будет трубить, тогда совершится тайна Божия, как\nОн благовестил Своим рабам пророкам.","8":"И голос, который я услышал с неба, снова говорил\nсо мной и сказал: иди, возьми книгу раскрытую в руке\nангела, стоящего на море и на земле.","9":"И я пошел к ангелу, говоря ему дать мне книжку.\nИ говорит мне: возьми и съешь её, и произведет она\nгоречь в твоем чреве, но в устах твоих она будет\nсладка, как мёд.","10":"И взял я книжку из руки ангела и съел её, и была\nона в устах моих словно мёд сладкий; и когда я съел её,\nстало горько во чреве моем.","11":"И\nговорят\nмне:\nдолжно\nтебе\nснова\nпророчествовать о народах, и племенах, и языках и\nцарях многих."},"11":{"1":"И была дана мне трость, подобная посоху, и\nсказано: встань и измерь храм Божий и жертвенник и\nпоклоняющихся в нем.","2":"И двор, что вне храма, оставь вне, и не измеряй\nего, потому что он дан был язычникам, и они будут\nпопирать город святой сорок два месяца,","3":"И дам двум свидетелям Моим, и они будут\nпророчествовать\nтысячу\nдвести\nшестьдесят\nдней,\nодетые во вретище.","4":"Это две маслины и два светильника, стоящие пред\nГосподом земли.","5":"И, если кто хочет причинить им вред, огонь\nисходит из уст их и пожирает врагов их; и, если кто\nзахочет причинить им вред, надлежит ему быть так\nубитым.","6":"Они имеют власть затворить небо, чтобы не шел\nдождь во дни пророчества их, и власть имеют над\nводами превращать их в кровь и поразить землю всякой\nязвой, когда только захотят.","7":"И когда они закончат свидетельство свое, зверь,\nподнимающийся из бездны, будет воевать против них, и\nпобедит их и убьет их.","8":"И трупы их – на улице города великого, который\nназывается духовно Содом и Египет, где и Господь их\nбыл распят.","9":"И люди из народов, и колен, и языков и племен\nсмотрят на трупы их три дня с половиной, и не\nпозволяют положить трупы их в гробницу.","10":"И живущие на земле радуются о них и веселятся,\nи дары будут посылать друг другу, потому что эти два\nпророка мучили живущих на земле.","11":"И после трех дней с половиной дух жизни от\nБога вошел в них, и они стали на ноги свои, и страх\nвеликий напал на тех, кто смотрели на них.","12":"И услышали они голос великий с неба, говорящий\nим: взойдите сюда; и они взошли на небо на облаке; и\nсмотрели на них враги их.","13":"И в тот час произошло землетрясение великое, и\nдесятая\nчасть\nгорода\nпала,\nи\nбыло\nубито\nв\nземлетрясении\nсемь\nтысяч\nимен\nчеловеческих,\nи\nостальные пришли в страх и воздали славу Богу\nНебесному.","14":"Второе горе прошло; вот третье горе идет скоро,","15":"и седьмой ангел вострубил; и раздались голоса\nвеликие на небе, говорящие: Царство мира стало\nЦарством Господа нашего и Христа Его, и будет Он\nцарствовать во веки веков.","16":"И двадцать четыре старца, сидящие пред Богом\nна престолах своих, пали на лица свои и поклонились\nБогу,","17":"говоря:\nБлагодарим\nТебя,\nГосподи\nБоже\nВседержитель, Тот, Кто есть и Кто был, что принял Ты\nсилу Твою великую и воцарился.","18":"И язычники разгневались, и пришел гнев Твой и\nвремя судить мёртвых и дать награду рабам Твоим\nпророкам и святым и боящимся имени Твоего, малым и\nвеликим, и погубить губящих землю.","19":"И открылся храм Божий, который на небе, и\nявился ковчег завета Его в храме Его, и произошли\nмолнии, и голоса, и громы, и землетрясение и град\nвеликий."},"12":{"1":"И знамение великое явилось на небе: жена,\nоблечённая в солнце, и луна под ногами её, и на голове\nеё венец из двенадцати звёзд,","2":"и она имеет во чреве и кричит, страдая и мучаясь,\nчтобы родить,","3":"И явилось другое знамение на небе, и вот дракон\nвеликий огненно-красный, имеющий семь голов и\nдесять рогов, и на головах его семь диадем;","4":"и хвост его увлекает треть звёзд небесных; и он\nповерг их на землю. И дракон стал перед женою,\nкоторой надлежало родить, чтобы, когда она родит,\nпожрать её младенца.","5":"И родила она сына мужеского пола, которому\nнадлежит пасти все народы посохом железным: и было\nвосхищено дитя её к Богу и к престолу Его.","6":"И жена убежала в пустыню, где она имеет место,\nуготованное Богом, чтобы там питали её тысячу двести\nшестьдесят дней.","7":"И произошла война на небе: Михаил и ангелы его\nвоевали с драконом. И дракон воевал, и ангелы его,","8":"и он не осилил, и не нашлось уже для них места\nна небе.","9":"И низвержен был дракон великий, змей древний,\nназываемый Диаволом и Сатаной, обманывающий всю\nвселенную; он был низвержен на землю, и ангелы его\nбыли низвержены с ним.","10":"И я услышал голос великий на небе, говорящий :\nТеперь настало спасение и сила и царство Бога нашего\nи власть Христа Его, потому что низвержен обвинитель\nбратьев наших, обвиняющий их пред Богом нашим день\nи ночь.","11":"И они его победили кровью Агнца и словом\nсвидетельства своего, и не возлюбили души своей даже\nдо смерти.","12":"Итак, веселитесь небеса и живущие на них! Горе\nземле и морю, потому что сошел диавол к вам, в ярости\nвеликой, зная, что мало у него времени.","13":"И, когда увидел дракон, что он низвержен на\nземлю, воздвиг он гонение на жену, которая родила\nмладенца мужеского пола.","14":"И даны были жене два крыла орла великого,\nчтобы она летела в пустыню в свое место: там она\nпитаема в течение времени и времён и полувремени\nвдали от змея.","15":"И пустил зверь из пасти своей вслед за женой\nводу как реку, чтобы унесло её рекой.","16":"И помогла земля жене, и разверзла земля уста\nсвои и поглотила реку, которую пустил дракон из пасти\nсвоей.","17":"И разгневался дракон на жену и пошел, чтобы\nвступить\nв\nсражение\nс\nпрочими\nот\nсемени\nеё,\nсоблюдающими\nзаповеди\nБожии\nи\nимеющими\nсвидетельство Иисуса.","18":"И он стал на песке морском."},"13":{"1":"И я увидел поднимающегося из моря зверя,\nимеющего десять рогов и семь голов, и на рогах его –\nдесять диадем, и на головах его – имена богохульные.","2":"И зверь, которого я увидел, был подобен барсу, и\nноги его словно у медведя, и пасть его словно пасть\nльва. И дал ему дракон силу свою и престол свой и\nвласть великую,","3":"И я увидел одну из голов его, словно пораженную\nсмертельно; и рана его смертельная была исцелена. И в\nудивлении вся земля пошла за зверем;","4":"и поклонились дракону, потому что он дал власть\nзверю, и поклонились зверю, говоря: кто подобен зверю,\nи кто может сразиться с ним?","5":"И даны ему были уста, говорящие великое и\nбогохульное, и дана ему была власть действовать сорок\nдва месяца.","6":"И открыл он уста свои для хулы на Бога, хулить\nимя Его и скинию Его, и живущих на небе.","7":"И дано ему было пойти войною на святых и\nпобедить их, и дана ему была власть над всяким\nколеном, и народом, и языком и племенем.","8":"И поклонятся ему все живущие на земле, которых\nимена не написаны в книге жизни у Агнца, закланного\nот сотворения мира.","9":"Если кто имеет ухо, да услышит.","10":"Если кому надлежит идти в плен, он идет в плен;\nесли кто убьёт мечом, надлежит тому быть у биту\nмечом. Здесь терпение и вера святых.","11":"И я увидел другого зверя, поднимающегося из\nземли, и он имел два рога, подобные агнчим, и говорил,\nкак дракон.","12":"И он действует со всей властью первого зверя\nперед ним. И он заставляет землю и живущих на ней\nпоклониться первому зверю, у которого была исцелена\nего смертельная рана.","13":"И он творит знамения великие, так что и огонь\nнизводит с неба на землю перед людьми.","14":"И\nобманывает\nживущих\nна\nземле\nтеми\nзнамениями, которые дано ему было сотворить перед\nзверем, говоря живущим на земле, чтобы они сделали\nобраз зверя, который имеет рану от меча и который\nожил.","15":"И дано ему было вложить дух в образ зверя так,\nчтобы образ зверя и заговорил и сделал, чтобы все,\nкоторые не поклонятся образу зверя, были убиты.","16":"И он поступает так, чтобы всем, малым и\nвеликим, и богатым и нищим, и свободным и рабам,\nдали клеймо на руку их правую или на лоб их,","17":"и чтобы никто не мог ни купить, ни продать,\nкроме того, кто имеет клеймо: или имя зверя, или число\nимени его.","18":"Здесь мудрость. Имеющий ум да сочтёт число\nзверя; ибо оно число человеческое. И число его\nшестьсот шестьдесят шесть."},"14":{"1":"И я увидел, и вот Агнец стоит на горе Сионе, и с\nНим сто сорок четыре тысячи, у которых имя Его и имя\nОтца Его написаны на челах их.","2":"И я услышал голос с неба, словно голос вод\nмногих и словно голос грома великого; и голос, который\nя\nуслышал,\nсловно\nиграющих\nна\nгуслях,\nсопровождающих гуслями пение свое.","3":"И поют они песнь новую пред престолом и перед\nчетырьмя животными и старцами: и никто не мог\nнаучиться этой песне, кроме этих ста сорока четырех\nтысяч, искупленных от земли.","4":"Это те, которые не осквернились с женщинами:\nибо они девственники. Это те, которые следуют за\nАгнцем, куда бы Он ни шел. Они были искуплены от\nлюдей, как начаток Богу и Агнцу,","5":"и в устах их не было найдено лжи: они непорочны.","6":"И я увидел другого ангела, летящего высоко в\nнебе, имеющего Евангелие вечное, чтобы благовестить\nсидящим на земле и всякому племени, и колену, и языку\nи народу.","7":"И говорил он голосом великим: убойтесь Бога и\nвоздайте Ему славу, потому что пришел час суда Его, и\nпоклонитесь Сотворившему небо, и землю, и море и\nисточники вод.","8":"И другой ангел, второй, последовал, говоря: пал,\nпал Вавилон великий, который напоил все народы от\nвина ярости и блуда своего.","9":"И еще один ангел, третий, последовал за ними,\nговоря голосом великим: если кто поклоняется зверю и\nобразу его и принимает клеймо на лоб свой или на руку\nсвою, –","10":"он будет пить от вина ярости Божией, вина\nцельного, приправленного в чаше гнева Его, и будет\nмучим в огне и сере перед ангелами святыми и пред\nАгнцем;","11":"и дым мучения их поднимается во веки веков; и\nне имеют покоя день и ночь поклоняющиеся зверю и\nобразу его, и всякий, кто принимает клеймо имени его.","12":"Здесь терпение святых: они соблюдают заповеди\nБожии и веру в Иисуса.","13":"И я услышал голос с неба, говорящий: напиши:\n«отныне блаженны мёртвые, в Господе умирающие. Да,\nговорит Дух: пусть они успокоятся от трудов своих; ибо\nдела их следуют за ними».","14":"И я увидел, и вот облако белое, и на облаке\nСидящий, подобный Сыну человека, имеющий на голове\nСвоей венец золотой и в руке Своей острый серп.","15":"И другой ангел вышел из храма, взывая голосом\nвеликим к Сидящему на облаке: пошли серп Твой и\nпожни, потому что пришел час жатвы, потому что\nсозрела жатва на земле.","16":"И поверг Сидящий на облаке серп Свой на землю\nи земля была пожата.","17":"И другой ангел вышел из храма, который на\nнебе, и у него тоже серп острый.","18":"И другой ангел вышел от жертвенника, имеющий\nвласть над огнем, и возгласил он голосом великим к\nимеющему серп острый, говоря: пошли острый серп\nтвой и собери гроздья на лозе земной, потому что\nпоспели ягоды её.","19":"И поверг ангел серп свой на землю и собрал с\nлозы земной и бросил в великое точило ярости Божией.","20":"И истоптано было точило за городом, и вышла\nкровь из точила даже до узд конских на тысячу\nшестьсот стадий."},"15":{"1":"И я увидел другое знамение на небе, великое и\nдивное: семь ангелов, имеющих семь последних язв,\nпотому что ими окончилась ярость Божия.","2":"И я увидел словно море стеклянное, смешанное с\nогнем, и побеждающих в борьбе со зверем и с образом\nего и с числом имени его, стоящих на море стеклянном,\nдержащих гусли Божии,","3":"И поют они песнь Моисея, раба Божия, и песнь\nАгнца, говоря: Велики и дивны дела Твои, Господи Боже\nВседержитель, праведны и истинны пути Твои, Царь\nнародов.","4":"Кто не убоится, Господи, и не прославит имени\nТвоего? потому что Ты един свят, потому что все\nнароды придут и преклонятся пред Тобою, потому что\nсуды Твои были явлены.","5":"И после этого я увидел, и открылся храм скинии\nсвидетельства на небе,","6":"и вышли из храма семь ангелов, имеющих семь\nязв, одетые в лён чистый, блестящий, и опоясанные по\nгрудь поясами золотыми.","7":"И одно из четырех животных дало семи ангелам\nсемь\nчаш\nзолотых,\nнаполненных\nяростью\nБога,\nживущего во веки веков.","8":"И наполнился храм дымом от славы Божией и от\nсилы Его, и никто не мог войти в храм, пока не\nокончатся семь язв семи ангелов."},"16":{"1":"И я услышал великий голос из храма, говорящий\nсеми ангелам: идите и вылейте семь чаш ярости\nБожией на землю.","2":"И пошел первый и вылил чашу свою на землю; и\nпоявились гнойные раны жестокие и злокачественные\nна людях, имеющих клеймо зверя и поклоняющихся\nобразу его.","3":"И второй вылил чашу свою в море: появилась\nкровь, словно мертвеца, и всё одушевлённое в море\nумерло.","4":"И третий вылил чашу свою в реки и источники вод:\nи появилась кровь.","5":"И я услышал ангела вод, говорящего: Праведен\nТы, Тот, Кто есть и Кто был, Свят Ты, что Ты так судил,","6":"потому что они пролили кровь святых и пророков,\nи Ты дал им пить кровь. Они того достойны.","7":"И я услышал жертвенник, говорящий: Да, Господи\nБоже Вседержитель, истинны и праведны суды Твои!","8":"И четвёртый вылил чашу свою на солнце: и дано\nбыло ему жечь людей огнем.","9":"И опалены были люди зноем великим и хулили имя\nБога, имеющего власть над этими язвами, и не\nпокаялись, чтобы воздать Ему славу.","10":"И пятый вылил чашу свою на престол зверя, и\nсделалось царство его мрачным, и кусали языки свои от\nболи.","11":"И хулили Бога небесного от страданий своих и от\nран своих, и не покаялись в делах своих.","12":"И шестой вылил чашу свою на реку великую\nЕвфрат, и высохла вода её, чтобы приготовлен был путь\nцарям, которые – от востока солнца.","13":"И я увидел выходящих из уст дракона, и из уст\nзверя и из уст лжепророка, трех духов нечистых словно\nлягушек.","14":"Ибо они – духи бесовские, творящие знамения;\nони выходят к царям всей вселенной, чтобы собрать их\nна сражение великого дня Бога Вседержителя.","15":"Вот, иду как вор: блажен бодрствующий и\nхранящий одежды свои, чтобы не ходить ему нагим, и\nчтобы не видели срама его.","16":"И они собрали их на место, называемое по-\nеврейски Армагедон.","17":"И седьмой вылил чашу свою на воздух: и исшел\nголос великий из храма от престола, говорящий:\nсбылось.","18":"И произошли молнии и голоса и громы, и\nземлетрясение произошло великое, какого не бывало с\nтех пор, как человек на земле, такое сильное, такое\nвеликое!","19":"И город великий распался на три части, и города\nнародов пали. И Вавилон великий воспомянут был пред\nБогом, чтобы дать ему чашу вина ярости гнева Его.","20":"И всякий остров убежал, и горы не были\nнайдены.","21":"И град великий, весом словно с талант, падает с\nнеба на людей; и хулили люди Бога за язву града,\nпотому что крайне велика эта язва."},"17":{"1":"И пришел один из семи ангелов, имеющих семь\nчаш, и говорил со мной и сказал: иди сюда, я покажу\nтебе суд над блудницей великой, сидящей на водах\nмногих,","2":"с которой впали в блуд цари земные, и опьянели\nнаселяющие землю от вина блуда её.","3":"И он перенёс меня в Духе в пустыню. И я увидел\nжену, сидящую на звере багряном, полном имен\nбогохульных, имеющем семь голов и десять рогов.","4":"И жена была облечена в пурпур и багряное и\nукрашена\nзолотом\nи\nкамнями\nдрагоценными\nи\nжемчугом, держа в руке своей золотую чашу, полную\nмерзостей и нечистоты блуда её.","5":"И на лбу её имя написанное, тайна: Вавилон\nвеликий, мать блудницам и мерзостям земным.","6":"И я увидел, что жена пьяна от крови святых и от\nкрови свидетелей Иисуса. И я удивился, увидев её,\nудивлением великим.","7":"И сказал мне ангел: почему ты удивился? я скажу\nтебе тайну жены и зверя, носящего её, имеющего семь\nголов и десять рогов.","8":"Зверь, которого ты увидел, был, и его нет; и он\nподнимется из бездны и в погибель идёт; и будут\nудивляться\nживущие\nна\nземле,\nкоторых\nимя\nне\nнаписано в книге жизни от основания мира, смотря на\nзверя, который был, и которого нет, и который придёт.","9":"Здесь ум, имеющий мудрость. Семь голов – это\nсемь гор, на которых жена сидит, и это – семь царей;","10":"пятеро пали, один есть, другой еще не пришел и,\nкогда придет, недолго ему должно оставаться,","11":"И зверь, который был и которого нет, он – и\nвосьмой, и из семи, и в погибель идёт.","12":"И десять рогов, которые ты увидел, это десять\nцарей, которые еще не получили царства, но на один\nчас получают власть словно цари вместе со зверем,","13":"Они имеют одно намерение, и дают силу и власть\nсвою зверю.","14":"Они сразятся с Агнцем, и Агнец победит их,\nпотому что Он Господь господствующих и Царь царей, и\nте, которые с Ним, званые и избранные и верные.","15":"И говорит мне: воды, которые ты увидел, где\nсидит блудница, это – люди и толпы и народы и языки.","16":"И десять рогов, которые ты увидел, и зверь\nвозненавидят блудницу и разорят её, и обнажат, и\nплоть её съедят, и сожгут её огнем.","17":"Ибо Бог вложил им в сердца исполнить волю Его,\nи исполнить одну эту волю и дать зверю царство их,\nпока не совершатся слова Божии.","18":"И жена, которую ты увидел, есть город великий,\nимеющий царство над царями земли."},"18":{"1":"После этого я увидел другого ангела, сходящего с\nнеба, и имеющего власть великую; и земля была\nосвещена славой его.","2":"И он воззвал сильным голосом, говоря: пал, пал\nВавилон великий, блудница, и сделался жилищем бесов\nи убежищем всякого духа нечистого и убежищем всякой\nнечистой и ненавистной птицы,","3":"потому что от вина ярости блуда её напились все\nнароды, и цари земные впали с нею в блуд, и купцы\nземные разбогатели от силы роскоши её.","4":"И я услышал другой голос с неба, говорящий:\nвыйдите из неё, народ Мой, чтобы не быть вам\nсоучастниками в грехах её, и чтобы не подвергнуться\nязвам её,","5":"потому что дошли её грехи до неба, и вспомнил\nБог неправды её.","6":"Воздайте ей, как и она воздала, и вдвое воздайте\nпо делам её. В чаше, в которой она растворила вино,\nрастворите ей вдвойне.","7":"Сколько она славила себя и роскошествовала,\nстолько воздайте ей мучением и скорбью, потому что в\nсердце своем она говорит: «сижу царицей, и я не вдова,\nи скорби не увижу».","8":"Поэтому в один день придут язвы её, смерть и\nскорбь и голод, и будет она сожжена огнем, потому что\nсилен Господь Бог, осудивший её.","9":"И будут плакать и бить себя над нею в грудь цари\nземные, впавшие с нею в блуд и роскошь, когда будут\nсмотреть на дым пожара её,","10":"стоя поодаль из-за страха мучения её, и говоря:\n«горе, горе, город великий, Вавилон, город крепкий!\nибо в один час пришел суд твой».","11":"И купцы земные плачут и скорбят о ней, потому\nчто товаров их никто больше не покупает:","12":"товаров\nзолотых\nи\nсеребряных,\nи\nкамней\nдрагоценных, и жемчуга, и виссона, и пурпура, и шелка,\nи багряницы, и всякого благовонного дерева, и всяких\nизделий из слоновой кости, и всяких изделий из самого\nдорогого дерева, и меди, и железа, и мрамора,","13":"и корицы, и благовоний, и фимиама, и мира, и\nладана, и вина, и елея, и крупчатки, и пшеницы, и\nскота, и овец, и коней, и колесниц, и рабов, притом и\nдуш человеческих.","14":"«И зрелых плодов, которых вожделеет твоя\nдуша, не стало у тебя, и всё тучное и блистательное\nпропало для тебя, и его больше не найдут».","15":"Торговавшие этим купцы, обогатившиеся от неё,\nбудут стоять поодаль из-за страха мучения её с плачем\nи скорбью,","16":"говоря: «горе, горе, город великий, облеченный в\nвиссон и пурпур и багряное, и украшенный золотом и\nдрагоценными камнями и жемчугом,","17":"потому что в один час обратилось в ничто такое\nбогатство». И всякий кормчий и всякий мореплаватель и\nморяки и все те, кто живут от моря, стали поодаль","18":"и начали кричать, смотря на дым пожара её, и\nговоря: какой город подобен городу великому!","19":"И они посыпали пылью головы свои и кричали с\nплачем и скорбью, говоря: горе, горе, город великий,\nдрагоценностями которого обогатились все, имеющие\nкорабли на море; ибо в один час он обратился в ничто.","20":"Веселись о ней небо, и святые, и апостолы и\nпророки, потому что судил Бог взыскать за вас с неё.","21":"И один сильный ангел взял великий камень,\nсловно мельничный, и поверг в море, говоря: с такой\nсилой повержен будет Вавилон, великий город, и уже\nне будет найден.","22":"И голоса играющих на гуслях, и певцов, и\nсвирельщиков и трубачей уже не услышат в тебе, и\nникакого ремесленника какого бы то ни было ремесла\nуже не найдут в тебе, и шума от жерновов уже не\nуслышат в тебе,","23":"и свет светильника уже не будет светить в тебе,\nи голоса жениха и невесты уже не услышат в тебе,\nпотому что купцы твои были вельможами земли, потому\nчто волшебством твоим были обмануты все народы.","24":"И в нём была найдена кровь пророков и святых и\nвсех убитых на земле."},"19":{"1":"После этого я услышал словно голос великий\nтолпы большой на небе. Они говорили: Аллилуйя!\nСпасение и слава и сила – Богу нашему,","2":"потому что истинны и праведны суды Его; потому\nчто Он судил блудницу великую, которая растлевала\nземлю блудом своим, и взыскал кровь рабов Своих от\nруки её.","3":"И\nвторично\nсказали:\nАллилуйя!\nИ\nдым\nеё\nподнимается во веки веков.","4":"И двадцать четыре старца и четыре животных\nпали и поклонились Богу, сидящему на престоле,\nговоря; Аминь! Аллилуйя!","5":"И голос от престола исшел, говорящий: Хвалите\nБога нашего, все рабы Его, боящиеся Его, малые и\nвеликие.","6":"И я услышал словно голос большой толпы, и\nсловно голос вод многих, и словно голос громов\nсильных, говорящих: Аллилуйя! Ибо воцарился Господь\nБог наш Вседержитель.","7":"Будем радоваться и ликовать и воздадим славу\nЕму, потому что наступил брак Агнца, и жена Его\nприготовила себя,","8":"и дано ей было облечься в виссон блестящий,\nчистый; ибо виссон есть праведные дела святых.","9":"И он говорит мне: напиши: «блаженны званные на\nбрачную вечерю Агнца». И говорит мне: эти слова –\nистинные слова Божии.","10":"И я пал к ногам его, чтобы поклониться ему. И он\nговорит мне: смотри не делай этого. Я соработник твой\nи братьев твоих, имеющих свидетельство Иисуса. Богу\nпоклонись.\nИбо\nсвидетельство\nИисуса\nесть\nдух\nпророчества.","11":"И я увидел отверстое небо, и вот конь белый, и\nСидящий на нем называется: Верный и Истинный, и Он\nправедно судит и воинствует.","12":"Глаза Его – пламя огня, и на голове Его много\nдиадем. Он имеет имя написанное, которого никто не\nзнает, кроме Его Самого,","13":"и облечён Он в одежду, обагрённую кровью, и\nнаречено имя Ему: Слово Божие.","14":"И воинства небесные следуют за Ним на конях\nбелых, одетые в виссон белый, чистый.","15":"И из уст Его исходит меч острый, чтобы им\nпоражать\nнароды.\nИ\nОн\nСам\nпасёт\nих\nпосохом\nжелезным, и Сам топчет точило вина ярости гнева Бога\nВседержителя.","16":"И Он имеет на одежде и на бедре Своем имя\nнаписанное: Царь царей и Господь господствующих.","17":"И я увидел одного ангела, стоящего на солнце, и\nон прокричал голосом великим, говоря всем птицам,\nлетящим высоко в небе: придите, соберитесь на\nвеликую вечерю Божию,","18":"чтобы\nпожрать\nплоть\nцарей\nи\nплоть\nтысяченачальников и плоть сильных, и плоть коней и\nсидящих на них и плоть всех, как свободных, так и\nрабов, и малых и великих.","19":"И я увидел зверя и царей земли и воинства их\nсобранные, чтобы сразиться с Сидящим на коне и с\nвоинством Его.","20":"И схвачен был зверь и с ним лжепророк,\nсотворивший\nперед\nним\nзнамения,\nкоторыми\nон\nобманул принявших клеймо зверя и поклоняющихся\nобразу его. Они живыми были брошены оба в озеро\nогненное, горящее серой.","21":"И остальные были убиты мечом Сидящего на\nконе, исшедшим из уст Его, и все птицы насытились\nплотью их."},"20":{"1":"И я увидел ангела, сходящего с неба, который\nимел ключ от бездны и цепь великую в руке своей.","2":"И он схватил дракона, змея древнего, который\nесть Диавол и Сатана, и связал его на тысячу лет,","3":"и бросил его в бездну, и заключил его, и положил\nнад ним печать, чтобы он уже не обманывал народы,\nпока не окончится тысяча лет; после этого ему\nнадлежит быть освобожденным на малое время.","4":"И я увидел престолы и сидящих на них, которым\nбыло\nдано\nсудить,\nи\nдуши\nобезглавленных\nза\nсвидетельство Иисуса и за слово Божие, а также тех,\nкоторые не поклонились ни зверю, ни образу его, и не\nприняли клейма на лоб и на руку свою. И они ожили и\nцарствовали со Христом тысячу лет.","5":"Остальные из мёртвых не ожили, пока не\nокончится тысяча лет.","6":"Это – воскресение первое. Блажен и свят\nимеющий участие в воскресении первом: над ним\nвторая\nсмерть\nне\nимеет\nвласти,\nно\nони\nбудут\nсвященниками Бога и Христа, и будут царствовать с\nНим тысячу лет.","7":"И, когда окончится тысяча лет, будет освобожден\nсатана из темницы своей,","8":"и выйдет, чтобы обмануть народы, которые на\nчетырех углах земли, Гога и Магога, собрать их на\nсражение; число их словно песок морской.","9":"И поднялись они на широту земли и окружили\nстан святых и город возлюбленный. И сошел огонь с\nнеба и пожрал их.","10":"И диавол, обманывающий их, был брошен в озеро\nогненное и серное, где зверь и лжепророк, и будут они\nмучимы день и ночь во веки веков.","11":"И я увидел великий белый престол и Сидящего\nна нем, от лица Которого бежали земля и небо, и места\nне было найдено для них.","12":"И я увидел мёртвых, великих и малых, стоящих\nпред престолом, и книги были раскрыты; и другая книга\nбыла раскрыта, которая есть книга жизни, и были\nсудимы мёртвые, согласно написанному в книгах, по\nделам своим.","13":"И отдало море мёртвых, бывших в нем, и смерть\nи ад отдали мёртвых, бывших в них, и они судимы были,\nкаждый по делам своим.","14":"И смерть и ад были брошены в озеро огненное.\nЭто – смерть вторая, озеро огненное.","15":"И, если кто не был найден записанным в книге\nжизни, он был брошен в озеро огненное."},"21":{"1":"И я увидел небо новое и землю новую; ибо\nпрежнее небо и прежняя земля ушли, и моря уже нет.","2":"И я увидел город святой, новый Иерусалим,\nсходящий с неба от Бога, приготовленный словно\nневеста, украшенная для мужа своего,","3":"И\nя\nуслышал\nголос\nвеликий\nот\nпрестола,\nговорящий: вот скиния Божия с людьми, и Он будет\nобитать с ними, и они будут Его народами, и Сам Бог\nбудет с ними,","4":"и отрёт всякую слезу с очей их, и смерти уже не\nбудет; ни скорби, ни крика, ни боли уже не будет,\nпотому что прежнее ушло.","5":"И сказал Сидящий на престоле: вот, Я всё делаю\nновым. И говорит: напиши, потому что эти слова верны\nи истинны.","6":"И сказал мне: они сбылись! Я – Альфа и Омега,\nНачало и Конец. Жаждущему Я дам от источника воды\nжизни даром.","7":"Побеждающий наследует это, и Я буду ему Богом,\nи он будет Мне сыном.","8":"Малодушных же, и неверных, и осквернённых, и\nубийц, и блудников, и волшебников, и идолослужителей\nи всех лжецов – участь их в озере, горящем огнем и\nсерой: это – смерть вторая.","9":"И пришел один из семи ангелов, имеющих семь\nчаш, наполненных семью последними язвами, и говорил\nсо мной и сказал: приди, я покажу тебе невесту, жену\nАгнца,","10":"И он перенёс меня в Духе на гору великую и\nвысокую, и показал мне город святой Иерусалим,\nсходящий с неба от Бога,","11":"имеющий славу Божию; светило его подобно\nдрагоценнейшему\nкамню,\nсловно\nкамню\nяспису,\nпрозрачному как кристалл.","12":"Он имеет стену великую и высокую, имеет\nдвенадцать ворот, и на воротах двенадцать ангелов, и\nимена написанные – имена двенадцати колен сынов\nИзраилевых.","13":"С Востока трое ворот, с Севера трое ворот, и с\nЮга трое ворот, и с Запада трое ворот.","14":"И стена города имеет двенадцать оснований, и\nна них двенадцать имён двенадцати апостолов Агнца.","15":"И говорящий со мной имел как меру трость\nзолотую, чтобы измерить город и ворота его и стену\nего.","16":"И город расположен четырехугольником, и длина\nего та же, что и ширина. И он измерил город тростью в\nдвенадцать тысяч стадий: длина и ширина и высота его\nравны.","17":"И измерил стену его: сто сорок четыре локтя,\nмера человека, которая есть мера ангела.","18":"И построена стена его из ясписа, и город –\nзолото чистое, подобное стеклу чистому.","19":"Основания стены города украшены всякими\nдрагоценными камнями: основание первое – яспис,\nвторое – сапфир, третье – халкидон, четвертое –\nизумруд,","20":"пятое – сардоникс, шестое – сардис, седьмое –\nхризолит, восьмое – берилл, девятое – топаз, десятое –\nхризопраз,\nодиннадцатое-гиацинт,\nдвенадцатое\n–\nаметист.","21":"И двенадцать ворот – двенадцать жемчужин:\nкаждые ворота были из одной жемчужины. И улица\nгорода – золото чистое, словно прозрачное стекло.","22":"И храма я не у видел в нем; ибо Господь Бог\nВседержитель – храм его, и Агнец.","23":"И город не имеет нужды ни в солнце, ни в луне,\nчтобы они светили ему; ибо слава Божия осветила его, и\nсветильник его – Агнец.","24":"И будут ходить народы в свете его, и цари земли\nприносят славу свою в него.","25":"И ворота его не будут затворяться днем, ибо\nночи там не будет;","26":"и принесут славу и честь народов в него.","27":"И не войдет в него ничто нечистое, никто\nтворящий мерзость и ложь, но только те, кто написаны\nв книге жизни у Агнца."},"22":{"1":"И он показал мне реку воды жизни, блестящую\nсловно кристалл, исходящую от престола Бога и Агнца.","2":"Посредине улицы его, и по ту и по другую сторону\nреки, древо жизни, приносящее двенадцать плодов,\nкаждый месяц дающее плод свой; и листья древа – для\nисцеления народов,","3":"И ничего проклятого уже не будет. И престол Бога\nи Агнца будет в нем, и рабы Его будут служить Ему,","4":"и будут видеть лицо Его, и имя Его будет на челах\nих.","5":"И ночи уже не будет, и не имеют они нужды в\nсвете светильника и в свете солнца, потому что Господь\nБог будет светить над ними, и они будут царствовать во\nвеки веков.","6":"И он сказал мне: эти слова верны и истинны, и\nГосподь Бог духов пророков послал ангела Своего\nпоказать рабам Своим, что должно произойти вскоре.","7":"И вот, гряду скоро. Блажен соблюдающий слова\nпророчества книги этой.","8":"И я, Иоанн, слышу и вижу это. И когда я услышал и\nувидел, я пал, чтобы поклониться пред ногами ангела,\nпоказывающего мне это.","9":"И он говорит мне: смотри, не делай этого: я –\nсоработник твой и братьев твоих пророков и тех, кто\nсоблюдают слова книги этой. Богу поклонись.","10":"И\nон\nговорит\nмне:\nне\nзапечатывай\nслов\nпророчества книги этой; ибо время близко.","11":"Творящий неправду да творит еще неправду, и\nскверный да оскверняет себя еще, а праведный да\nтворит еще праведное, и святой да освящается еще.","12":"Вот, гряду скоро, и награда Моя со Мной, чтобы\nвоздать каждому по делам его.","13":"Я – Альфа и Омега, Первый и Последний, Начало\nи Конец.","14":"Блаженны – омывающие одежды свои, чтобы\nиметь им право на древо жизни и войти в город\nворотами.","15":"А вне – псы, и волшебники, и блудники, и убийцы,\nи идолослужители, и всякий любящий и совершающий\nложь.","16":"Я,\nИисус,\nпослал\nангела\nМоего\nзасвидетельствовать вам это о церквах. Я – корень и\nрод Давидов, звезда яркая, утренняя.","17":"И Дух и Невеста говорят: гряди. И слышащий да\nскажет: гряди. И жаждущий пусть приходит, желающий\nпусть берет воду жизни даром.","18":"Я свидетельствую всякому слышащему слова\nпророчества книги этой: если кто приложит к ним,\nналожит Бог на него язвы, написанные в книге этой.","19":"И, если кто отнимет от слов книги пророчества\nэтого, отнимет от него Бог участие в древе жизни и в\nгороде святом, и в том, что написано в книге этой.","20":"Свидетельствующий это говорит: да, гряду\nскоро. Аминь, гряди, Господи Иисусе!","21":"Благодать Господа Иисуса со всеми."}};
